# Average false positive rates over seven detectors, March 2023
# (Liang et al.): human essays wrongly flagged as AI-generated
FPR = {"US 8th-grade essays": 0.0519, "TOEFL essays": 0.6122}

for group, fpr in FPR.items():
    print(f"{group}: {50 * fpr:.0f} of 50 human essays flagged")


def wrong_flags(ai_share, tpr, fpr):
    """Share of flagged texts that a human actually wrote."""
    caught = ai_share * tpr
    accused = (1 - ai_share) * fpr
    return accused / (caught + accused)


# Hypothetical detector: catches 90% of AI text, flags 5% of human
# text, used where 1 submission in 10 is AI-written
print(f"{wrong_flags(0.10, 0.90, 0.05):.0%} of flags hit a human")
